from stream_models import StreamEvent


class EventBuffer:
    def __init__(self) -> None:
        self._events: list[StreamEvent] = []

    def append(self, event: StreamEvent) -> None:
        self._events.append(event)

    def pop_batch(self, limit: int) -> list[StreamEvent]:
        batch = self._events[:limit]
        self._events = self._events[limit:]
        return batch

    def restore_front(self, events: list[StreamEvent]) -> None:
        self._events = list(events) + self._events

    def __len__(self) -> int:
        return len(self._events)

    def ids(self) -> list[str]:
        return [event.event_id for event in self._events]

