"""Producer-facing stream ingestion workflow."""

from buffer import EventBuffer
from sink_adapter import BoundedSinkRecord
from stream_models import StreamEvent, StreamResult
from telemetry import TelemetryRecord
from watermarks import WatermarkPolicyRecord


class StreamIngestor:
    def __init__(self, policy: WatermarkPolicyRecord, sink: BoundedSinkRecord, telemetry: TelemetryRecord | None = None) -> None:
        self.policy = policy
        self.sink = sink
        self.telemetry = telemetry or TelemetryRecord("stream")
        self.buffer = EventBuffer()
        self.paused = False

    def ingest(self, event: StreamEvent) -> dict:
        high = self.policy.metadata.get("high", 100)
        if len(self.buffer) > high:
            self.paused = True
            self.telemetry.metadata["paused"] = self.telemetry.metadata.get("paused", 0) + 1
            return StreamResult(False, "paused", len(self.buffer), event.event_id).as_dict()
        self.buffer.append(event)
        self.telemetry.metadata["accepted"] = self.telemetry.metadata.get("accepted", 0) + 1
        return StreamResult(True, "accepted", len(self.buffer), event.event_id).as_dict()

    def flush(self, limit: int | None = None) -> dict:
        batch_size = limit or self.policy.metadata.get("flush_batch", 10)
        batch = self.buffer.pop_batch(batch_size)
        accepted_count = self.sink.write_many(batch)
        leftover = batch[accepted_count:]
        if leftover:
            self.buffer.restore_front(leftover)
        low = self.policy.metadata.get("low", 10)
        if len(self.buffer) <= low:
            self.paused = False
