from stream_models import make_event
from workflow import StreamIngestor, ingest_many
from watermarks import WatermarkPolicyRecord
from sink_adapter import BoundedSinkRecord


def ingestor(high=2, low=1, capacity=10):
    return StreamIngestor(WatermarkPolicyRecord("p", metadata={"high": high, "low": low, "flush_batch": capacity}), BoundedSinkRecord("s", metadata={"capacity": capacity, "written": []}))


def test_accepts_event_under_high_watermark():
    assert ingestor().ingest(make_event("e1", 1))["status"] == "accepted"


def test_pauses_at_high_watermark_boundary():
    s = ingestor(high=1)
    s.ingest(make_event("e1", 1))
    assert s.ingest(make_event("e2", 2))["status"] == "paused"


def test_paused_event_is_not_queued():
    s = ingestor(high=1)
    s.ingest(make_event("e1", 1))
    s.ingest(make_event("e2", 2))
    assert len(s.buffer) == 1


def test_order_is_preserved_when_flushing():
    s = ingestor(high=5)
    for i in range(3):
        s.ingest(make_event(f"e{i}", i))
    s.flush(3)
    assert [event.event_id for event in s.sink.metadata["written"]] == ["e0", "e1", "e2"]


def test_partial_sink_write_restores_unwritten_front():
    s = ingestor(high=5, capacity=1)
    s.ingest(make_event("e1", 1)); s.ingest(make_event("e2", 2))
    s.flush(2)
    assert s.buffer.ids() == ["e2"]


def test_flush_reports_only_accepted_sink_count():
    s = ingestor(high=5, capacity=1)
    s.ingest(make_event("e1", 1)); s.ingest(make_event("e2", 2))
    assert s.flush(2)["flushed"] == 1


def test_low_watermark_resumes_stream():
    s = ingestor(high=1, low=0, capacity=10)
    s.ingest(make_event("e1", 1)); s.ingest(make_event("e2", 2))
    s.flush(1)
    assert s.paused is False


def test_telemetry_counts_accepted_events():
    s = ingestor(high=3)
    s.ingest(make_event("e1", 1))
    assert s.telemetry.metadata["accepted"] == 1


def test_telemetry_counts_paused_events():
    s = ingestor(high=1)
    s.ingest(make_event("e1", 1)); s.ingest(make_event("e2", 2))
    assert s.telemetry.metadata.get("paused") == 1


def test_telemetry_counts_flushed_events():
    s = ingestor(high=3)
    s.ingest(make_event("e1", 1))
    s.flush(1)
    assert s.telemetry.metadata["flushed"] == 1


def test_ingest_many_returns_result_per_event():
    assert len(ingest_many([make_event("a", 1), make_event("b", 2)], high=5, low=1, sink_capacity=2)["results"]) == 2


def test_rejected_result_keeps_event_id_for_retry():
    s = ingestor(high=1)
    s.ingest(make_event("e1", 1))
    assert s.ingest(make_event("e2", 2))["event_id"] == "e2"


def test_common_wrong_fix_does_not_drop_boundary_event_silently():
    s = ingestor(high=1)
    s.ingest(make_event("e1", 1))
    result = s.ingest(make_event("e2", 2))
    assert result["accepted"] is False and result["queued"] == 1


def test_flush_empty_buffer_is_noop():
    assert ingestor().flush(5)["flushed"] == 0


def test_sink_capacity_zero_keeps_all_events_buffered():
    s = ingestor(high=5, capacity=0)
    s.ingest(make_event("e1", 1))
    s.flush(1)
    assert s.buffer.ids() == ["e1"]


def test_result_dictionary_keys_are_stable():
    assert set(ingestor().ingest(make_event("e1", 1))) == {"accepted", "status", "queued", "event_id"}


def test_flush_dictionary_keys_are_stable():
    assert set(ingestor().flush(1)) == {"flushed", "queued", "paused"}


def test_multiple_tenants_do_not_change_order():
    s = ingestor(high=5)
    s.ingest(make_event("e1", 1, "t2")); s.ingest(make_event("e2", 2, "t1"))
    assert s.buffer.ids() == ["e1", "e2"]


def test_high_watermark_uses_current_queue_before_append():
    s = ingestor(high=0)
    assert s.ingest(make_event("e1", 1))["status"] == "paused"


def test_after_partial_flush_paused_state_remains_when_above_low():
    s = ingestor(high=1, low=0, capacity=1)
    s.ingest(make_event("e1", 1)); s.ingest(make_event("e2", 2)); s.flush(1)
    assert s.paused is True
